<script setup lang="ts">
import Icon from '../components/Icon.vue';
import IconButton from '../components/IconButton.vue';
import ImageComposer from '../components/ImageComposer.vue';
import ImagePreview from '../components/ImagePreview.vue';
import VoiceMessage from '../components/VoiceMessage.vue';
import { messageVoice,voiceTranscript } from '../voices';
import { messageImage,visibleMessageText,type ImageJob } from '../images';
import { useEvents } from '../events';
import { ref,reactive,nextTick,onMounted,onUnmounted } from 'vue';import { useRoute } from 'vue-router';import { api,auth,json,type Scope } from '../api';import { names,type Channel,type Message,type Profile } from '../types';import { Timeline } from '../timeline';import ChatSettings from '../components/ChatSettings.vue';
const route=useRoute(),scope:Scope={world:String(route.query.conversation||'default'),channel:(['group','wan','yan','liu'].includes(String(route.query.channel))?String(route.query.channel):'group') as Channel};
const timeline=reactive(new Timeline()),input=ref(''),status=ref(''),settings=ref(false),chat=ref<HTMLElement>(),sending=ref(0),loading=ref(true),polling=ref(false),suggesting=ref(false),options=ref<string[]>([]),profile=ref<Profile>({title:names[scope.channel],avatar:''}),states=ref<Record<string,string>>({}),avatars=ref<Record<string,string>>({});
const visibleKey='account:'+auth.scope+':status:'+scope.world+':'+scope.channel,showStatus=ref(localStorage.getItem(visibleKey)!=='false'),draftKey='chat-draft:'+auth.scope+':'+location.pathname+location.search;
let lastRead='',receiptPending=false,scenePending=false,stopped=false,pollAgain=false,sceneAgain=false;
const newest=()=>timeline.messages.filter(m=>!m.pending).at(-1);
function atBottom(){return !!chat.value&&chat.value.scrollHeight-chat.value.scrollTop-chat.value.clientHeight<80;}
async function markRead(){const latest=newest();if(!latest||document.hidden||!atBottom()||receiptPending||latest.id===lastRead)return;receiptPending=true;try{await api('/api/messages/read',{method:'POST',body:json({message_id:latest.id})},scope);lastRead=latest.id;localStorage.setItem('companion-read-changed',String(Date.now()));}catch{}finally{receiptPending=false;}}
async function poll(initial=false){if(stopped||document.hidden)return;if(polling.value){pollAgain=true;return;}polling.value=true;const epoch=timeline.epoch,stick=initial||atBottom(),latest=newest();try{const query=latest?'?incremental=true&after='+encodeURIComponent(latest.id):'';const data=await api<{messages:Message[];delta:boolean;unchanged:boolean}>('/api/messages'+query,{},scope);if(epoch!==timeline.epoch||stopped)return;if(!data.unchanged){timeline.receive(data.messages,data.delta,epoch);await nextTick();if(chat.value&&stick)chat.value.scrollTop=chat.value.scrollHeight;}if(!failedRun.value)status.value='';}catch(e){status.value=(e as Error).message;}finally{polling.value=false;loading.value=false;await markRead();if(pollAgain){pollAgain=false;poll();}}}
async function refresh(){try{const info=await api<{scene_state:Record<string,string>;role_avatars:Record<string,string>}>('/api/info?details=false',{},scope);states.value=info.scene_state;avatars.value=info.role_avatars;profile.value=await api<Profile>('/api/conversation/profile',{},scope);document.title=profile.value.title;}catch(e){status.value=(e as Error).message;}}
async function refreshScene(){if(document.hidden||!showStatus.value||stopped)return;if(scenePending){sceneAgain=true;return;}scenePending=true;try{states.value=(await api<{scene_state:Record<string,string>}>('/api/scene',{},scope)).scene_state;}catch{}finally{scenePending=false;if(sceneAgain){sceneAgain=false;refreshScene();}}}
async function send(){const text=input.value.trim();if(!text)return;const request=crypto.randomUUID(),epoch=timeline.epoch;const pending:Message={id:'pending:'+request,role:'user',content:text,created_at:Date.now()/1000,pending:true};timeline.messages.push(pending);input.value='';options.value=[];sending.value++;await nextTick();if(chat.value)chat.value.scrollTop=chat.value.scrollHeight;
 try{const result=await api<{id:string;message_id:string}>('/api/send',{method:'POST',body:json({request_id:request,messages:[{role:'user',content:text}]})},scope);if(epoch===timeline.epoch){const item=timeline.messages.find(m=>m.id===pending.id);if(item)item.id=result.message_id;status.value='已送达';watchRun(result.id);} }
 catch(e){timeline.messages=timeline.messages.filter(m=>m.id!==pending.id);if(!input.value)input.value=text;status.value=(e as Error).message;}
 finally{sending.value--;poll();}}
async function watchRun(id:string){if(stopped||document.hidden)return;watchedRuns.add(id);try{const state=await api<{status:string}>('/api/send/'+id,{},scope);if(state.status==='failed'){watchedRuns.delete(id);status.value='角色回复失败，可重试';failedRun.value=id;}else if(!['pending','running'].includes(state.status)){watchedRuns.delete(id);poll();refreshImages();}}catch{}}
const failedRun=ref('');async function retry(){try{await api('/api/send/'+failedRun.value+'/retry',{method:'POST'},scope);watchRun(failedRun.value);failedRun.value='';status.value='已重新排队';}catch(e){status.value=(e as Error).message;}}
async function clearDisplay(){if(sending.value){status.value='消息正在送达，请稍等片刻再清空';return;}try{await api('/api/messages/clear-display',{method:'POST'},scope);timeline.clear();lastRead='';settings.value=false;localStorage.setItem('companion-read-changed',String(Date.now()));}catch(e){status.value=(e as Error).message;}}
async function suggest(){if(suggesting.value)return;suggesting.value=true;try{options.value=(await api<{options:string[]}>('/api/describe',{method:'POST',body:json({messages:timeline.messages.map(m=>({role:m.role,content:m.content}))}),signal:AbortSignal.timeout(120000)},scope)).options;}catch(e){status.value=(e as Error).message;}finally{suggesting.value=false;}}
function setStatus(value:boolean){showStatus.value=value;localStorage.setItem(visibleKey,String(value));}
function expire(event:Event){const detail=(event as CustomEvent).detail;if(detail.changed)return;let text=input.value;try{const sent=JSON.parse(detail.body||'{}').messages?.filter((m:Message)=>m.role==='user').map((m:Message)=>m.content).join('\n');text=[sent,text].filter(Boolean).join('\n');}catch{}if(text)sessionStorage.setItem(draftKey,text);}
function visibility(){if(!document.hidden){poll();refreshScene();}}
function speaker(message:Message){return message.speaker||message.content.match(/^(小婉|小研|小柳)[：:]/)?.[1]||names[scope.channel];}
function body(message:Message){if(messageImage(message)||messageVoice(message))return '';return message.role==='user'?message.content:visibleMessageText(message.content).replace(/^(小婉|小研|小柳|图片)[：:]\s*/,'').trim();}
const imageDialog=ref(false),imageBusy=ref(false),imageError=ref(''),imageJobs=ref<ImageJob[]>([]),preview=ref<{id:string;alt:string}>();
let imagePending=false,imageRequestId='',imageRequestKey='',imageTimer:ReturnType<typeof setInterval>;
const dismissedImages=new Set<string>();
async function refreshImages(){if(stopped||document.hidden||imagePending)return;imagePending=true;try{imageJobs.value=(await api<ImageJob[]>('/api/images',{},scope)).filter(j=>!dismissedImages.has(j.id));if(!imageJobs.value.some(j=>['pending','running'].includes(j.status)))await poll();}catch{}finally{imagePending=false;}}
async function generateImage(prompt:string,size:string,actor:string){if(imageBusy.value)return;imageBusy.value=true;imageError.value='';const key=JSON.stringify({prompt,size,actor});if(imageRequestKey!==key){imageRequestId='';imageRequestKey=key;}imageRequestId ||= crypto.randomUUID();try{const job=await api<ImageJob>('/api/images',{method:'POST',body:json({prompt,size,actor,request_id:imageRequestId})},scope);imageRequestId='';input.value='';imageDialog.value=false;imageJobs.value=[job,...imageJobs.value.filter(j=>j.id!==job.id)];await poll();refreshImages();}catch(e){imageError.value=(e as Error).message;status.value=imageError.value;}finally{imageBusy.value=false;}}
function openImage(){imageError.value='';imageDialog.value=true;}
function retryImage(job:ImageJob){imageRequestId='';generateImage(job.prompt,job.size,job.actor);}
async function dismissImage(id:string){try{await api('/api/images/'+encodeURIComponent(id)+'/dismiss',{method:'POST'},scope);dismissedImages.add(id);imageJobs.value=imageJobs.value.filter(j=>j.id!==id);}catch(e){status.value=(e as Error).message;}}
const watchedRuns=new Set<string>();
useEvents(()=>{poll();refreshScene();refreshImages();for(const id of watchedRuns)watchRun(id);});
let pollTimer:ReturnType<typeof setInterval>,sceneTimer:ReturnType<typeof setInterval>;
onMounted(()=>{input.value=sessionStorage.getItem(draftKey)||'';sessionStorage.removeItem(draftKey);window.addEventListener('auth-expired',expire);document.addEventListener('visibilitychange',visibility);refresh();poll(true);refreshImages();imageTimer=setInterval(()=>{if(imageJobs.value.some(j=>['pending','running'].includes(j.status)))refreshImages();},3000);pollTimer=setInterval(()=>{poll();for(const id of watchedRuns)watchRun(id);},30000);sceneTimer=setInterval(refreshScene,30000);});
onUnmounted(()=>{stopped=true;clearInterval(imageTimer);clearInterval(pollTimer);clearInterval(sceneTimer);watchedRuns.clear();window.removeEventListener('auth-expired',expire);document.removeEventListener('visibilitychange',visibility);});
</script>
<template><div class="chat-page"><header><RouterLink to="/" class="back" aria-label="返回主页" title="返回主页"><Icon name="back" :size="24"/></RouterLink><div class="chat-title"><img v-if="profile.display_avatar||profile.avatar" :src="profile.display_avatar||profile.avatar" alt="">{{profile.title}}</div><IconButton icon="settings" label="设置" @click="settings=true"/></header><section v-if="showStatus" class="character-states" aria-label="三人状态"><span v-for="name in ['小婉','小研','小柳']" :key="name"><strong>{{name}}</strong>{{states[name]||'暂无新动态'}}</span></section><main ref="chat" class="chat-messages" @scroll.passive="markRead"><p v-if="loading" class="muted empty">正在读取聊天…</p><article v-for="message in timeline.messages" :key="message.id" class="message" :class="{mine:message.role==='user',pending:message.pending}"><div v-if="message.role==='assistant'" class="message-avatar"><img v-if="avatars[speaker(message)]" :src="avatars[speaker(message)]" alt="" decoding="async"><span v-else>{{speaker(message).slice(1)}}</span></div><div class="message-body"><small v-if="message.role==='assistant'">{{speaker(message)}}</small><VoiceMessage v-if="messageVoice(message)" :identity="messageVoice(message)" :transcript="voiceTranscript(message)" :scope="scope"/><p v-if="!messageImage(message) && !messageVoice(message) && body(message)">{{body(message)}}</p><button v-if="messageImage(message)" class="message-image" type="button" aria-label="查看生成图片" @click="preview={id:messageImage(message),alt:'聊天图片'}"><img :src="'/api/images/'+messageImage(message)+'/content'" alt="聊天图片" loading="lazy" decoding="async" @load="markRead"/></button></div></article><article v-for="job in imageJobs.filter(j=>j.status!=='done')" :key="job.id" class="image-task" :aria-busy="job.status!=='failed'"><div><strong>{{job.status==='failed'?'图片未生成':job.status==='pending'?'准备拍照':'正在拍照'}}</strong><p v-if="job.status==='failed'">{{job.error}}</p><small v-if="job.status!=='failed'">拍好就发给你，你可以继续聊天。</small></div><IconButton v-if="job.status==='failed'" icon="refresh" label="重新生成" @click="retryImage(job)" :busy="imageBusy"/><IconButton v-if="job.status==='failed'" icon="close" label="关闭" @click="dismissImage(job.id)"/></article></main><section class="composer"><div v-if="options.length" class="suggestions"><button v-for="option in options" :key="option" @click="input=option;options=[]">{{option}}</button></div><form @submit.prevent="send"><textarea v-model="input" aria-label="输入消息" placeholder="写下此刻想说的话…" rows="2" @keydown.enter.exact.prevent="send"/><IconButton icon="image" label="图片" @click="openImage" :busy="imageBusy"/><IconButton icon="wand" label="描述" @click="suggest" :busy="suggesting"/><IconButton icon="send" label="发送" type="submit" class="primary" :disabled="!input.trim()"/></form><div class="composer-status" role="status"><span>{{status}}</span><IconButton v-if="failedRun" icon="refresh" label="重试" @click="retry"/></div></section><ImageComposer v-if="imageDialog" :initial="input" :channel="scope.channel" :busy="imageBusy" :error="imageError" @close="imageDialog=false" @generate="generateImage"/><ImagePreview v-if="preview" :identity="preview.id" :alt="preview.alt" @close="preview=undefined"/><ChatSettings v-if="settings" :scope="scope" :show-status="showStatus" @close="settings=false" @changed="refresh" @clear="clearDisplay" @status="setStatus"/></div></template>
